{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": "Mean accumulated shadow (min)",
  "encoding": {
    "theta": {
      "field": "Mean Acc shadow",
      "type": "quantitative",
      "stack": true
    },
    "color": {
      "field": "scenario_name",
      "type": "nominal",
      "legend": null
    }
  },
  "layer": [
    {
      "mark": {
        "type": "arc",
        "outerRadius": 110,
        "tooltip": true
      }
    },
    {
      "mark": {
        "type": "text",
        "radius": 135
      },
      "encoding": {
        "text": {
          "field": "Mean Acc shadow",
          "type": "quantitative",
          "format": ".2f"
        }
      }
    }
  ]
}

# The size of the change from Existing (input_0) to Towers removed (input_1),
# cell by cell: 0 where they agree.
return curio_raster_calculate("subtract", [input_1, input_0], absolute=True)

